package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w360dp-h780dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class HotfixV095Test {
 private AppRegressionTest base;private MainActivity a;private VehicleCoordinator model;private Jobs jobs;
 static final class Jobs extends AbstractExecutorService {final List<Runnable> tasks=new ArrayList<>();public void execute(Runnable r){tasks.add(r);}public void shutdown(){}public List<Runnable> shutdownNow(){return Collections.emptyList();}public boolean isShutdown(){return false;}public boolean isTerminated(){return false;}public boolean awaitTermination(long t,TimeUnit unit){return true;}}
 @Before public void setup()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);model=VehicleCoordinator.get(a);model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="HOTFIX-TEST";Field signed=VehicleCoordinator.class.getDeclaredField("signedIn");signed.setAccessible(true);signed.setBoolean(model,true);model.snapshot=new VehicleSnapshot("Polestar 2","masked",78,312,12000,"空闲","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");jobs=new Jobs();Field queue=VehicleCoordinator.class.getDeclaredField("commandIO");queue.setAccessible(true);((ExecutorService)queue.get(model)).shutdownNow();queue.set(model,jobs);}
 @After public void cleanup(){base.stop();}
 private Object call(String name,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(a,args);}
 private void render()throws Exception{call("render",new Class<?>[0]);View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(780,1073741824));root.layout(0,0,360,780);}
 @Test public void defaultsRemainBiometricAndEachActionHasAnIndependentPolicy(){for(String action:ControlAuthorization.ACTIONS)assertEquals("biometric",ControlAuthorization.mode(a,action));AppPreferences.set(a,"control_action_auth_unlock","direct");assertEquals("direct",ControlAuthorization.mode(a,"unlock"));assertEquals("biometric",ControlAuthorization.mode(a,"lock"));AppPreferences.set(a,"control_action_auth_unlock","invalid");assertEquals("biometric",ControlAuthorization.mode(a,"unlock"));}
 @Test public void repeatRequiresConsentAndRetainsOriginalActionEvenAfterStateChanges()throws Exception{AppPreferences.set(a,"control_action_auth_unlock","direct");model.command("unlock");assertEquals(1,jobs.tasks.size());assertTrue(model.canControl("lock"));assertFalse(model.canDispatch("lock",true));model.snapshot=new VehicleSnapshot("Polestar 2","masked",78,312,12000,"空闲","全部关闭","全部关闭","已关闭","未锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");call("directControl",new Class<?>[]{String.class},"lock");AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(d.isShowing());d.getButton(-2).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(1,jobs.tasks.size());call("directControl",new Class<?>[]{String.class},"lock");d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();d.getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(1,jobs.tasks.size());assertTrue(model.repeatQueued("lock"));assertEquals("unlock",model.pendingAction("lock"));}
 @Test public void confirmationCancelAndVinChangeNeverDispatch()throws Exception{AppPreferences.set(a,"control_action_auth_unlock","confirm");call("authenticate",new Class<?>[]{String.class,String.class},"Unlock","unlock");org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getButton(-2).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(0,jobs.tasks.size());call("authenticate",new Class<?>[]{String.class,String.class},"Unlock","unlock");model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="OTHER-CAR";org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(0,jobs.tasks.size());}
 @Test public void directModeQueuesExactlyOneWriteWithoutBiometricPrompt()throws Exception{AppPreferences.set(a,"control_action_auth_unlock","direct");call("authenticate",new Class<?>[]{String.class,String.class},"Unlock","unlock");assertEquals(1,jobs.tasks.size());assertEquals("unlock",model.pendingAction("lock"));}
 @Test public void allSkinsRetainStatusCampIconsAndRespectBatteryBarSwitch()throws Exception{for(String skin:UiSkin.pickerChoices()){UiSkin.set(a,skin);for(String theme:new String[]{"light","dark"}){AppPreferences.set(a,"theme",theme);AppPreferences.set(a,"show_battery_bar","off");render();View root=a.getWindow().getDecorView();TextView condition=root.findViewWithTag("exterior_button"),camp=root.findViewWithTag("camp_button");assertNotNull(skin,condition);assertNotNull(skin,camp);assertTrue(skin,condition.getText().length()>0);assertTrue(skin,camp.getText().length()>0);assertTrue(skin,hasGlyph(condition));assertTrue(skin,hasGlyph(camp));View bar=root.findViewWithTag("vi_progress");assertNotNull(skin,bar);assertEquals(skin,View.GONE,bar.getVisibility());AppPreferences.set(a,"show_battery_bar","on");render();assertEquals(skin,View.VISIBLE,a.getWindow().getDecorView().findViewWithTag("vi_progress").getVisibility());}}}
 private boolean hasGlyph(TextView v){for(android.graphics.drawable.Drawable d:v.getCompoundDrawablesRelative())if(d!=null)return true;return false;}
 @Test public void momentaryCommandsFinishWithoutUnverifiableReadbacks()throws Exception{model.command("honk");Field pending=VehicleCoordinator.class.getDeclaredField("pendingCommands");pending.setAccessible(true);Object ticket=((Map<?,?>)pending.get(model)).get("signal");Field accepted=ticket.getClass().getDeclaredField("accepted");accepted.setAccessible(true);accepted.setBoolean(ticket,true);Method confirm=VehicleCoordinator.class.getDeclaredMethod("confirmCommand",ticket.getClass());confirm.setAccessible(true);confirm.invoke(model,ticket);assertFalse(model.commandPending);assertEquals(OperationState.SERVER_ACCEPTED,model.operation);Field readback=ticket.getClass().getDeclaredField("readback");readback.setAccessible(true);assertNull(readback.get(ticket));}
 @Test public void connectionAndCommandStateShareOneRowAcrossAllSkins()throws Exception{for(String skin:UiSkin.pickerChoices()){UiSkin.set(a,skin);model.operation=OperationState.VEHICLE_CONFIRMED;render();View root=a.getWindow().getDecorView();TextView connection=root.findViewWithTag("vehicle_connection_state"),progress=root.findViewWithTag("command_status_progress");assertSame(connection.getParent(),progress.getParent());assertEquals(connection.getTop(),progress.getTop());assertTrue(connection.getText().toString().endsWith(" · "));assertFalse(progress.getText().toString().contains("Updated"));assertEquals(LinearLayout.HORIZONTAL,((LinearLayout)connection.getParent()).getOrientation());}}
 @Test public void questionHelpStartsCollapsedAndExpandsInPlace(){LinearLayout p=new LinearLayout(a);HelpDisclosure.add(p,a,"Help","Supplement");LinearLayout group=(LinearLayout)p.getChildAt(0);TextView q=(TextView)group.getChildAt(0);View detail=group.getChildAt(1);assertTrue(q.getText().toString().startsWith("?"));assertEquals(View.GONE,detail.getVisibility());q.performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(View.VISIBLE,detail.getVisibility());q.performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(View.GONE,detail.getVisibility());}
 @Test public void energyHistoryOpensWhenSignedOutWithoutSelectedVehicle()throws Exception{model.selected=null;Field signed=VehicleCoordinator.class.getDeclaredField("signedIn");signed.setAccessible(true);signed.setBoolean(model,false);call("energyHistory",new Class<?>[0]);Intent intent=Shadows.shadowOf(a).getNextStartedActivity();assertNotNull(intent);assertEquals(EnergyActivity.class.getName(),intent.getComponent().getClassName());}
 @Test public void widgetBatteryPreferenceAppliesToEveryNativeDesign(){for(String style:new String[]{VoLikeWidgetRenderer.CLASSIC,VoLikeWidgetRenderer.SIMPLE,VoLikeWidgetRenderer.DETAILED,VoLikeWidgetRenderer.POLESTAR,VoLikeWidgetRenderer.PSEU}){AppPreferences.set(a,"widget_design",style);AppPreferences.set(a,"show_battery_bar","off");View root=WidgetRenderer.createNativeViews(a,0,WidgetRenderer.Size.LARGE,360,180,null,model.snapshot,style).apply(a,new FrameLayout(a));assertEquals(style,View.GONE,root.findViewById(R.id.widget_soc_progress).getVisibility());}}
}
